 router.get('/players',auth,async(req,res)=>{const f=filterSchema.parse(req.query),sport=z.enum(sports).optional().parse(req.query.sport),skill=z.enum(['Beginner','Intermediate','Advanced','All levels']).optional().parse(req.query.skill);const r=await database().query(`select p.id,p.name,p.username,p.bio,p.avatar_path as "avatarPath",p.city_id as "cityId",p.area_id as "areaId",coalesce((select jsonb_agg(jsonb_build_object('sport',sport,'skill',skill)) from public.player_sports where player_id=p.id),'[]') sports from public.profiles p join app_private.accounts a on a.id=p.id where a.status='active' and p.city_id=$1 and ($2::text is null or p.area_id=$2) and not public.blocked(p.id,$3) and ($4::text is null or exists(select 1 from public.player_sports where player_id=p.id and sport=$4 and ($5::text is null or skill=$5))) order by p.name,p.id limit $6 offset $7`,[f.cityId,f.areaId||null,identity(res).userId,sport||null,skill||null,f.pageSize,(f.page-1)*f.pageSize]);res.json({data:await Promise.all(r.rows.map(async row=>{const {avatarPath,...publicRow}=row;return {...publicRow,avatarUrl:await avatarUrl(avatarPath as string|null)}})),page:f.page,pageSize:f.pageSize})});
