 router.get('/me/connections',auth,async(_req,res)=>{const id=identity(res).userId;res.json({data:(await database().query(`select c.requester_id as "requesterId",c.recipient_id as "recipientId",c.status,p.id,p.name from public.player_connections c join public.profiles p on p.id=case when c.requester_id=$1 then c.recipient_id else c.requester_id end where (c.requester_id=$1 or c.recipient_id=$1) and not public.blocked(c.requester_id,c.recipient_id) order by c.created_at desc limit 100`,[id])).rows})});
 router.post('/connections/:id',auth,async(req,res)=>{const id=idSchema.parse(req.params.id),p=z.object({type:z.enum(['request','accept','remove','block','unblock'])}).strict().parse(req.body),me=identity(res).userId;if(id===me)throw new HttpError(400,'INVALID_INPUT','Choose another player.');await asActor(res,async tx=>{
  const active=await tx.query("select id from app_private.accounts where id=$1 and status='active'",[id]);if(!active.rows.length)throw new HttpError(404,'NOT_FOUND','Player unavailable.');
  if(p.type==='block'){await tx.query('insert into public.player_blocks(blocker_id,blocked_id) values($1,$2) on conflict do nothing',[me,id]);await tx.query('delete from public.player_connections where (requester_id=$1 and recipient_id=$2) or (requester_id=$2 and recipient_id=$1)',[me,id]);}
  else if(p.type==='unblock')await tx.query('delete from public.player_blocks where blocker_id=$1 and blocked_id=$2',[me,id]);
  else if(p.type==='remove')await tx.query('delete from public.player_connections where (requester_id=$1 and recipient_id=$2) or (requester_id=$2 and recipient_id=$1)',[me,id]);
  else{const blocked=await tx.query<{blocked:boolean}>('select public.blocked($1,$2) blocked',[me,id]);if(blocked.rows[0].blocked)throw new HttpError(403,'FORBIDDEN','Interaction blocked.');if(p.type==='request')await tx.query('insert into public.player_connections(requester_id,recipient_id) values($1,$2)',[me,id]);else{const r=await tx.query("update public.player_connections set status='accepted' where requester_id=$1 and recipient_id=$2 and status='pending' returning requester_id",[id,me]);if(!r.rows.length)throw new HttpError(404,'NOT_FOUND','Incoming request not found.');}}
 });res.json({ok:true})});
